17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        String telephone = toE164(owner.getTelephone());
110	        if (telephone == null) {
111	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
112	        }
113	        if (owner.getEmail() != null) {
114	            String email = normalizeEmail(owner.getEmail());
115	            if (email == null) {
116	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	            }
118	            owner.setEmail(email);
119	        }
120	        for (Owner existing : this.clinicService.findAllOwners()) {
121	            if (telephone.equals(toE164(existing.getTelephone()))) {
122	                return new ResponseEntity<>(HttpStatus.CONFLICT);
123	            }
124	        }
125	        String lastNameKey = householdKey(owner.getLastName());
126	        String addressKey = householdKey(owner.getAddress());
127	        List<Owner> householdMembers = new ArrayList<>();
128	        for (Owner existing : this.clinicService.findAllOwners()) {
129	            if (lastNameKey.equals(householdKey(existing.getLastName()))
130	                && addressKey.equals(householdKey(existing.getAddress()))) {
131	                householdMembers.add(existing);
132	            }
133	        }
134	        if (!householdMembers.isEmpty()) {
135	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
136	                return new ResponseEntity<>(HttpStatus.CONFLICT);
137	            }
138	            String householdId = householdId(lastNameKey, addressKey);
139	            owner.setHouseholdId(householdId);
140	            for (Owner member : householdMembers) {
141	                if (!householdId.equals(member.getHouseholdId())) {
142	                    member.setHouseholdId(householdId);
143	                    this.clinicService.saveOwner(member);
144	                }
145	            }
146	        }
147	        owner.setTelephone(telephone);
148	        if (owner.getRegistrationDate() == null) {
149	            owner.setRegistrationDate(LocalDate.now());
150	        }
151	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
152	        this.clinicService.saveOwner(owner);
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
163	        if (currentOwner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        currentOwner.setAddress(ownerFieldsDto.getAddress());
167	        currentOwner.setCity(ownerFieldsDto.getCity());
168	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	        currentOwner.setLastName(ownerFieldsDto.getLastName());
170	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
171	        this.clinicService.saveOwner(currentOwner);
172	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Transactional
177	    @Override
178	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        this.clinicService.deleteOwner(owner);
184	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
190	        Owner owner = this.clinicService.findOwnerById(ownerId);
191	        if (owner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        HttpHeaders headers = new HttpHeaders();
195	        Pet pet = petMapper.toPet(petFieldsDto);
196	        owner.setId(ownerId);
197	        pet.setOwner(owner);
198	        pet.getType().setName(null);
199	        this.clinicService.savePet(pet);
200	        PetDto petDto = petMapper.toPetDto(pet);
201	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
202	            .buildAndExpand(pet.getId()).toUri());
203	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
209	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
210	        if (currentOwner != null) {
211	            Pet currentPet = this.clinicService.findPetById(petId);
212	            if (currentPet != null) {
213	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
214	                currentPet.setName(petFieldsDto.getName());
215	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
216	                this.clinicService.savePet(currentPet);
217	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
218	            }
219	        }
220	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	    }
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
226	        HttpHeaders headers = new HttpHeaders();
227	        Visit visit = visitMapper.toVisit(visitFieldsDto);
228	        Pet pet = new Pet();
229	        pet.setId(petId);
230	        visit.setPet(pet);
231	        this.clinicService.saveVisit(visit);
232	        VisitDto visitDto = visitMapper.toVisitDto(visit);
233	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
234	            .buildAndExpand(visit.getId()).toUri());
235	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
236	    }
237	
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
242	        Owner owner = this.clinicService.findOwnerById(ownerId);
243	        if (owner != null) {
244	            Pet pet = owner.getPet(petId);
245	            if (pet != null) {
246	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
247	            }
248	        }
249	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
250	    }
251	
252	    /**
253	     * Builds the customer code for a newly created owner, formatted
254	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
255	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
256	     * sequence equal to one more than the current number of owners.
257	     *
258	     * @param lastName the owner's last name
259	     * @return the assigned customer code (e.g. {@code 'SMI-0007'})
260	     */
261	    private String nextCustomerCode(String lastName) {
262	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
263	        int sequence = this.clinicService.findAllOwners().size() + 1;
264	        return String.format("%s-%04d", last3, sequence);
265	    }
266	
267	    /**
268	     * Normalizes a last name or address for household-duplicate comparison: leading and
269	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
270	     * single space and the result is lower-cased. Two owners are considered to share a
271	     * household when both their last names and addresses produce the same key.
272	     *
273	     * @param value the raw last name or address value
274	     * @return the normalized comparison key (empty string when {@code value} is null)
275	     */
276	    private static String householdKey(String value) {
277	        if (value == null) {
278	            return "";
279	        }
280	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
281	    }
282	
283	    /**
284	     * Derives the stable shared household identifier for the given normalized last name
285	     * and address keys. The identifier is deterministic — the same household (same
286	     * {@link #householdKey normalized} last name and address) always maps to the same
287	     * value — so every owner who joins a household is assigned an identical id. It is the
288	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
289	     * '<lastNameKey>|<addressKey>'}.
290	     *
291	     * @param lastNameKey the normalized last name key
292	     * @param addressKey  the normalized address key
293	     * @return the shared household identifier
294	     */
295	    private static String householdId(String lastNameKey, String addressKey) {
296	        String source = lastNameKey + "|" + addressKey;
297	        try {
298	            byte[] digest = MessageDigest.getInstance("SHA-256")
299	                .digest(source.getBytes(StandardCharsets.UTF_8));
300	            StringBuilder hex = new StringBuilder(digest.length * 2);
301	            for (byte b : digest) {
302	                hex.append(String.format("%02x", b));
